#include <stdio.h>
#include <string.h>

typedef struct { char buf[512]; int len; } Query;

void q_init(Query *q) { q->buf[0] = '\0'; q->len = 0; }
void q_select(Query *q, char *cols) { q->len = sprintf(q->buf, "SELECT %s", cols); }
void q_from(Query *q, char *table) { q->len += sprintf(q->buf + q->len, " FROM %s", table); }
void q_where(Query *q, char *cond) { q->len += sprintf(q->buf + q->len, " WHERE %s", cond); }

int main() {
    Query q;
    q_init(&q);
    q_select(&q, "name, age");
    q_from(&q, "users");
    q_where(&q, "age > 18");
    printf("%s\n", q.buf);
    return 0;
}
